50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
58	    private Set<Pet> pets;
59	
60	    public String getAddress() {
61	        return this.address;
62	    }
63	
64	    public void setAddress(String address) {
65	        this.address = address;
66	    }
67	
68	    public String getCity() {
69	        return this.city;
70	    }
71	
72	    public void setCity(String city) {
73	        this.city = city;
74	    }
75	
76	    public String getTelephone() {
77	        return this.telephone;
78	    }
79	
80	    public void setTelephone(String telephone) {
81	        this.telephone = telephone;
82	    }
83	
84	    public String getEmail() {
85	        return this.email;
86	    }
87	
88	    public void setEmail(String email) {
89	        this.email = email;
90	    }
91	
92	    public LocalDate getRegistrationDate() {
93	        return this.registrationDate;
94	    }
95	
96	    public void setRegistrationDate(LocalDate registrationDate) {
97	        this.registrationDate = registrationDate;
98	    }
99	
100	    /**
101	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
102	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
103	     */
104	    @Transient
105	    public String getDisplayName() {
106	        return this.getLastName() + ", " + this.getFirstName();
107	    }
108	
109	    /**
110	     * The owner's initials: the upper-cased first letters of firstName and lastName,
111	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
112	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
113	     */
114	    @Transient
115	    public String getInitials() {
116	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
117	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
118	    }
119	
120	    protected Set<Pet> getPetsInternal() {
121	        if (this.pets == null) {
122	            this.pets = new HashSet<>();
123	        }
124	        return this.pets;
125	    }
126	
127	    protected void setPetsInternal(Set<Pet> pets) {
128	        this.pets = pets;
129	    }
130	
131	    public List<Pet> getPets() {
132	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
133	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
134	        return Collections.unmodifiableList(sortedPets);
135	    }
136	
137	    public void setPets(List<Pet> pets) {
138	        this.pets = new HashSet<>(pets);
139	    }
140	
141	    public void addPet(Pet pet) {
142	        getPetsInternal().add(pet);
143	        pet.setOwner(this);
144	    }
145	
146	    /**
147	     * Return the Pet with the given name, or null if none found for this Owner.
148	     *
149	     * @param name to test
150	     * @return true if pet name is already in use
151	     */
152	    public Pet getPet(String name) {
153	        return getPet(name, false);
154	    }
155	
156	    /**
157	     * Return the Pet with the given name, or null if none found for this Owner.
158	     *
159	     * @param name to test
160	     * @return true if pet name is already in use
161	     */
162	    public Pet getPet(String name, boolean ignoreNew) {
163	        name = name.toLowerCase();
164	        for (Pet pet : getPetsInternal()) {
165	            if (!ignoreNew || !pet.isNew()) {
166	                String compName = pet.getName();
167	                compName = compName.toLowerCase();
168	                if (compName.equals(name)) {
169	                    return pet;
170	                }
171	            }
172	        }
173	        return null;
174	    }
175	
176	    public Pet getPet(Integer petId) {
177	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
178	    }
179	
180	    @Override
181	    public String toString() {
182	        return new ToStringCreator(this)
183	
184	            .append("id", this.getId())
185	            .append("new", this.isNew())
186	            .append("lastName", this.getLastName())
187	            .append("firstName", this.getFirstName())
188	            .append("address", this.address)
189	            .append("city", this.city)
190	            .append("telephone", this.telephone)
191	            .toString();
192	    }
193	}
